public boolean shouldPrintMessage(int timestamp, String message) {
    // Use a HashMap to store the last printed timestamp for each message
    HashMap<String, Integer> messageTimestampMap = new HashMap<>();

    // Check if the message is already in the map
    if (messageTimestampMap.containsKey(message)) {
        // Get the last printed timestamp for the message
        int lastPrintedTimestamp = messageTimestampMap.get(message);

        // If the current timestamp is less than or equal to the last printed timestamp plus 10 seconds, return false
        if (timestamp <= lastPrintedTimestamp + 10) {
            return false;
        }
    }

    // Update the last printed timestamp for the message
    messageTimestampMap.put(message, timestamp);

    // Return true to indicate the message should be printed
    return true;
}

