public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null || node == null) {
        throw new IllegalArgumentException("Output and node cannot be null");
    }

    int totalSize = 0;

    while (node != null) {
        byte[] buffer = node.buffer;
        out.write(buffer, node.offset, node.length);
        totalSize += node.length;

        LinkedBuffer next = node.next;
        node.clear(); // Clear the current node for garbage collection
        node = next;
    }

    return totalSize;
}

